old='''  int count=p.getInt("pending",0);String names=p.getString("names","");boolean offline=p.getBoolean("offline",false);\n  Bundle options=m.getAppWidgetOptions(id);int height=options==null?0:options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,0);boolean compact=height>0&&height<175;\n  v.setTextViewText(R.id.widget_pending,count+" pending order"+(count==1?"":"s"));\n  v.setTextViewText(R.id.widget_mode,offline?"OFFLINE • PHONE COPY":"SYNCED WITH PC");\n  v.setTextViewText(R.id.widget_names,names.isEmpty()?(count==0?"No pending orders. Add one when a customer calls.":"Tap Open pending to review orders."):names);\n  v.setViewVisibility(R.id.widget_mode,compact?android.view.View.GONE:android.view.View.VISIBLE);\n  v.setViewVisibility(R.id.widget_names,compact?android.view.View.GONE:android.view.View.VISIBLE);\n  v.setOnClickPendingIntent(R.id.widget_add,activity(c,OrdersActivity.ACTION_NEW,31));\n  v.setOnClickPendingIntent(R.id.widget_open,activity(c,null,32));\n  v.setOnClickPendingIntent(R.id.widget_refresh,refresh(c));\n  v.setOnClickPendingIntent(R.id.widget_names,activity(c,null,34));\n  v.setOnClickPendingIntent(R.id.widget_pending,activity(c,null,35));\n  m.updateAppWidget(id,v);'''
new='''  int count=p.getInt("pending",0);String p1=p.getString("party1","");String p2=p.getString("party2","");String p3=p.getString("party3","");int more=p.getInt("moreParties",0);boolean offline=p.getBoolean("offline",false);\n  Bundle options=m.getAppWidgetOptions(id);int height=options==null?0:options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,0);boolean compact=height>0&&height<190;\n  v.setTextViewText(R.id.widget_pending,String.valueOf(count));\n  v.setTextViewText(R.id.widget_mode,offline?"PHONE OFFLINE":"PC SYNCED");\n  v.setTextViewText(R.id.widget_party1,p1.isEmpty()?(count==0?"No pending orders":"Open pending orders"):p1);\n  v.setTextViewText(R.id.widget_party2,p2);\n  v.setTextViewText(R.id.widget_party3,p3);\n  v.setTextViewText(R.id.widget_more,more>0?"+"+more+" more customer"+(more==1?"":"s"):"");\n  v.setViewVisibility(R.id.widget_mode,compact?android.view.View.GONE:android.view.View.VISIBLE);\n  v.setViewVisibility(R.id.widget_party_label,compact?android.view.View.GONE:android.view.View.VISIBLE);\n  v.setViewVisibility(R.id.widget_party2,!compact&&!p2.isEmpty()?android.view.View.VISIBLE:android.view.View.GONE);\n  v.setViewVisibility(R.id.widget_party3,!compact&&!p3.isEmpty()?android.view.View.VISIBLE:android.view.View.GONE);\n  v.setViewVisibility(R.id.widget_more,!compact&&more>0?android.view.View.VISIBLE:android.view.View.GONE);\n  v.setOnClickPendingIntent(R.id.widget_add,activity(c,OrdersActivity.ACTION_NEW,31));\n  v.setOnClickPendingIntent(R.id.widget_open,activity(c,null,32));\n  v.setOnClickPendingIntent(R.id.widget_refresh,refresh(c));\n  v.setOnClickPendingIntent(R.id.widget_party1,activity(c,null,34));\n  v.setOnClickPendingIntent(R.id.widget_party2,activity(c,null,36));\n  v.setOnClickPendingIntent(R.id.widget_party3,activity(c,null,37));\n  v.setOnClickPendingIntent(R.id.widget_pending,activity(c,null,35));\n  m.updateAppWidget(id,v);'''
assert old in s;s=s.replace(old,new)
old=''' private static void cache(Context context,JSONObject data,boolean offline){JSONArray a=data.optJSONArray("pending");StringBuilder names=new StringBuilder();if(a!=null){for(int i=0;i<Math.min(3,a.length());i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;if(names.length()>0)names.append(" • ");names.append(o.optString("buyer",o.optString("number")));}}context.getSharedPreferences(PREFS,Context.MODE_PRIVATE).edit().putInt("pending",data.optInt("pendingCount")).putString("names",names.toString()).putBoolean("offline",offline).apply();}'''
new=''' private static void cache(Context context,JSONObject data,boolean offline){JSONArray a=data.optJSONArray("pending");java.util.LinkedHashSet<String> parties=new java.util.LinkedHashSet<>();if(a!=null){for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String name=o.optString("buyer",o.optString("number")).trim();if(!name.isEmpty())parties.add(name);}}java.util.ArrayList<String> list=new java.util.ArrayList<>(parties);String p1=list.size()>0?list.get(0):"",p2=list.size()>1?list.get(1):"",p3=list.size()>2?list.get(2):"";int more=Math.max(0,list.size()-3);context.getSharedPreferences(PREFS,Context.MODE_PRIVATE).edit().putInt("pending",data.optInt("pendingCount")).putString("party1",p1).putString("party2",p2).putString("party3",p3).putInt("moreParties",more).putBoolean("offline",offline).apply();}'''
assert old in s;s=s.replace(old,new);p.write_text(s)

(root/'android/app/src/main/java/in/tallybridge/app/ProformaWidget.java').write_text('''package in.tallybridge.app;\n\nimport android.app.PendingIntent;\nimport android.appwidget.AppWidgetManager;\nimport android.appwidget.AppWidgetProvider;\nimport android.content.Context;\nimport android.content.Intent;\nimport android.widget.RemoteViews;\n\n/** One-tap 1x1 shortcut that opens a fresh proforma invoice draft. */\npublic final class ProformaWidget extends AppWidgetProvider {\n @Override public void onUpdate(Context context, AppWidgetManager manager, int[] ids){\n  for(int id:ids){\n   RemoteViews v=new RemoteViews(context.getPackageName(),R.layout.quick_pi_widget);\n   Intent i=new Intent(context,MainActivity.class).setAction(MainActivity.ACTION_NEW_PROFORMA);\n   PendingIntent p=PendingIntent.getActivity(context,4101,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);\n   v.setOnClickPendingIntent(R.id.quick_widget_root,p);\n   manager.updateAppWidget(id,v);\n  }\n }\n}\n''')
(root/'android/app/src/main/java/in/tallybridge/app/QuickOrderWidget.java').write_text('''package in.tallybridge.app;\n\nimport android.app.PendingIntent;\nimport android.appwidget.AppWidgetManager;\nimport android.appwidget.AppWidgetProvider;\nimport android.content.Context;\nimport android.content.Intent;\nimport android.widget.RemoteViews;\n\n/** One-tap 1x1 shortcut for capturing a new phone order. */\npublic final class QuickOrderWidget extends AppWidgetProvider {\n @Override public void onUpdate(Context context, AppWidgetManager manager, int[] ids){\n  for(int id:ids){\n   RemoteViews v=new RemoteViews(context.getPackageName(),R.layout.quick_order_widget);\n   Intent i=new Intent(context,OrdersActivity.class).setAction(OrdersActivity.ACTION_NEW);\n   PendingIntent p=PendingIntent.getActivity(context,4102,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);\n   v.setOnClickPendingIntent(R.id.quick_widget_root,p);\n   manager.updateAppWidget(id,v);\n  }\n }\n}\n''')

